package ama.transcript;
import java.util.*;
import static ama.contract.MinutesContracts.*;
import static ama.contract.MinutesContracts.FailureCode.*;
/** One immutable publication identity validator, used before any producer or receipt capability. */
final class PublicationManifest {
 private static final Set<String> KEYS=Set.of("schema","providerId","storeInstanceId","clientId","delegationKeyId","assertionKeyId","publicationId","confirmationId","requesterId","businessKey","libraryId","folderId","logicalRequestHash","executionRequestHash","payloadSha256","archiveIndexSha256","renderArtifact","meetingId","businessVersion","cancelEpoch","executionNo","submissionNo","priorProofs");
 /** Validate the original stored wire outside roots; never normalize persisted bytes. */
 static Map<String,Object> read(String original,TranscriptAcquisitionBudget.Ledger budget){try{return readOriginal(original,budget);}catch(Failure failure){if(failure.code()==BUDGET_EXCEEDED||failure.code()==CANCELLED)throw failure;throw fail(PROVENANCE_UNAVAILABLE);}catch(IllegalArgumentException malformed){throw fail(PROVENANCE_UNAVAILABLE);}}
 private static Map<String,Object> readOriginal(String original,TranscriptAcquisitionBudget.Ledger budget){
  require(original!=null,PROVENANCE_UNAVAILABLE);long units=original.length(),points=original.codePointCount(0,original.length());budget.capture(Math.multiplyExact(units,3),points,units,8);byte[] bytes=original.getBytes(java.nio.charset.StandardCharsets.UTF_8);require(bytes.length>0&&bytes.length<=65536,BUDGET_EXCEEDED);var fields=ControlledKnowledgeClient.parse(bytes,65536);validate(fields,budget);byte[] canonical=ControlledKnowledgeClient.canonical(fields,budget);budget.capture(canonical.length,canonical.length,canonical.length,2);require(Arrays.equals(bytes,canonical),PROVENANCE_UNAVAILABLE);return fields;
 }
 static void validate(Map<String,Object> m,TranscriptAcquisitionBudget.Ledger budget){
  Objects.requireNonNull(budget);budget.row(m.size());
  var keys=new HashSet<>(m.keySet());keys.remove("bindingTransition");keys.remove("acceptanceBinding");require(keys.equals(KEYS)&&"ama.knowledge-publication-manifest.v1".equals(m.get("schema")),PROVENANCE_UNAVAILABLE);
  if(m.containsKey("acceptanceBinding")){require(m.get("acceptanceBinding") instanceof Map<?,?>,PROVENANCE_UNAVAILABLE);var binding=(Map<?,?>)m.get("acceptanceBinding");require(binding.keySet().equals(Set.of("schema","operation","receiptScopeHash","requestHash"))&&"ama.publication-command-acceptance.v1".equals(binding.get("schema"))&&binding.get("operation") instanceof String&&Set.of("PUBLICATION_SUBMIT","PUBLICATION_RESUBMIT","PUBLICATION_ZERO_EFFECT_RETRY").contains(binding.get("operation")),PROVENANCE_UNAVAILABLE);require(text(binding,"receiptScopeHash",64).matches("[0-9a-f]{64}")&&text(binding,"requestHash",64).matches("[0-9a-f]{64}"),PROVENANCE_UNAVAILABLE);}
  for(String k:List.of("publicationId","confirmationId","meetingId"))uuid(text(m,k,36));
  for(String k:List.of("providerId","storeInstanceId","clientId","delegationKeyId","assertionKeyId","requesterId","libraryId","folderId"))text(m,k,255);
  for(String k:List.of("logicalRequestHash","executionRequestHash","payloadSha256","archiveIndexSha256"))hash(text(m,k,64));
  require((m.get("publicationId")+":"+m.get("confirmationId")).equals(m.get("businessKey")),PROVENANCE_UNAVAILABLE);
  number(m.get("businessVersion"),0);number(m.get("cancelEpoch"),0);long execution=number(m.get("executionNo"),1),submission=number(m.get("submissionNo"),1);require(execution<=submission,PROVENANCE_UNAVAILABLE);
  require(m.get("renderArtifact") instanceof Map<?,?>,PROVENANCE_UNAVAILABLE);var render=(Map<?,?>)m.get("renderArtifact");require(render.keySet().equals(Set.of("version","sha256")),PROVENANCE_UNAVAILABLE);text(render,"version",255);hash(text(render,"sha256",64));
  require(m.get("priorProofs") instanceof List<?>,PROVENANCE_UNAVAILABLE);var proofs=(List<?>)m.get("priorProofs");require(proofs.size()<submission&&proofs.size()<=256,PROVENANCE_UNAVAILABLE);String previous="";
  for(var item:proofs){require(item instanceof Map<?,?>,PROVENANCE_UNAVAILABLE);var proof=(Map<?,?>)item;require(proof.keySet().equals(Set.of("executionId","executionRequestHash","receiptId","proofDigest")),PROVENANCE_UNAVAILABLE);String id=text(proof,"executionId",36);uuid(id);require(previous.compareTo(id)<0,PROVENANCE_UNAVAILABLE);previous=id;hash(text(proof,"executionRequestHash",64));hash(text(proof,"proofDigest",64));require(text(proof,"receiptId",40).matches("receipt-[0-9a-f]{32}"),PROVENANCE_UNAVAILABLE);}
  Object value=m.get("bindingTransition");if(proofs.isEmpty())require(value==null,PROVENANCE_UNAVAILABLE);else{
   require(value instanceof Map<?,?>,PROVENANCE_UNAVAILABLE);var transition=(Map<?,?>)value;require(transition.keySet().equals(Set.of("schema","expectedGeneration","priorProofs","newBusinessKey","newLogicalRequestHash"))&&"ama.controlled-kb-binding-transition.v1".equals(transition.get("schema")),PROVENANCE_UNAVAILABLE);
   // The pinned provider starts at generation 1 and increments once per accepted durable
   // receipt. Full authenticated predecessor membership is checked separately against history.
   require(number(transition.get("expectedGeneration"),1)==proofs.size()&&proofs.equals(transition.get("priorProofs"))&&m.get("businessKey").equals(transition.get("newBusinessKey"))&&m.get("logicalRequestHash").equals(transition.get("newLogicalRequestHash")),PROVENANCE_UNAVAILABLE);
  }
  require(ControlledKnowledgeClient.digest(ControlledKnowledgeClient.canonical(Map.of("schema","ama.knowledge-publish-execution.v1","logicalRequestHash",m.get("logicalRequestHash"),"executionNo",m.get("executionNo"),"priorProofs",proofs),budget)).equals(m.get("executionRequestHash")),FINGERPRINT_MISMATCH);
 }
 static void history(Map<String,Object> m,PublicationGraph.Plan plan){var budget=plan.budget();validate(m,budget);budget.row(plan.rows().get("publication_submission").size());long selected=((Number)m.get("submissionNo")).longValue();var priorTasks=new HashSet<String>();var submissions=plan.rows().get("publication_submission").stream().filter(s->m.get("publicationId").equals(s.get("publication_id"))&&((Number)s.get("submission_no")).longValue()<selected).toList();require(submissions.size()==selected-1,PROVENANCE_UNAVAILABLE);long ordinal=0;for(var s:submissions.stream().sorted(Comparator.comparingLong(x->((Number)x.get("submission_no")).longValue())).toList()){
   require(((Number)s.get("submission_no")).longValue()==++ordinal&&priorTasks.add((String)s.get("task_id")),PROVENANCE_UNAVAILABLE);
   budget.row(plan.rows().get("durable_task").size()+plan.rows().get("task_attempt").size()+plan.rows().get("external_execution").size()+plan.rows().get("publication_attempt").size());String task=(String)s.get("task_id");var tasks=plan.rows().get("durable_task").stream().filter(t->task.equals(t.get("id"))).toList();require(tasks.size()==1,PROVENANCE_UNAVAILABLE);var t=tasks.getFirst();require(Set.of("FAILED","CANCELLED","STALE").contains(t.get("state"))&&t.get("output_kind")==null&&t.get("output_id")==null&&s.get("logical_request_hash").equals(t.get("input_fingerprint")),PROVENANCE_UNAVAILABLE);
   var attempts=plan.rows().get("task_attempt").stream().filter(a->task.equals(a.get("task_id"))).toList();require(attempts.size()==((Number)t.get("attempt")).longValue()&&attempts.stream().allMatch(a->a.get("ended_at")!=null),PROVENANCE_UNAVAILABLE);
   var executions=plan.rows().get("external_execution").stream().filter(e->task.equals(e.get("task_id"))).toList();require(executions.size()<=1,PROVENANCE_UNAVAILABLE);var e=executions.isEmpty()?null:executions.getFirst();
   var published=plan.rows().get("publication_attempt").stream().filter(a->e!=null&&e.get("id").equals(a.get("execution_id"))).toList();
   if(e==null||e.get("marked_at")==null){
    require("NEVER_MARKED".equals(s.get("local_state"))&&s.get("local_decided_at")!=null&&s.get("local_decided_by")!=null&&s.get("local_reason")!=null&&Objects.equals(s.get("local_attempt_no"),t.get("attempt"))&&Objects.equals(s.get("local_execution_id"),e==null?null:e.get("id"))&&published.isEmpty(),PROVENANCE_UNAVAILABLE);
    if(e!=null)require("FAILED".equals(e.get("state"))&&"NOT_SENT".equals(e.get("no_effect_basis"))&&e.get("task_attempt")==null&&e.get("no_effect_verified_at")!=null&&Long.valueOf(1).equals(e.get("no_effect_evidence_present")),PROVENANCE_UNAVAILABLE);
   }else require("FAILED".equals(t.get("state"))&&"UNDECIDED".equals(s.get("local_state"))&&e.get("task_attempt")!=null&&s.get("execution_request_hash").equals(e.get("request_hash"))&&published.size()==1&&"FAILED".equals(published.getFirst().get("outcome"))&&published.getFirst().get("finished_at")!=null&&s.get("publication_id").equals(published.getFirst().get("publication_id"))&&s.get("confirmation_id").equals(published.getFirst().get("confirmation_id"))&&e.get("operation_id").equals(published.getFirst().get("operation_id")),PROVENANCE_UNAVAILABLE);
  }var references=new ArrayList<Map<String,Object>>();for(var e:plan.rows().get("external_execution")){if(!priorTasks.contains(e.get("task_id"))||e.get("marked_at")==null)continue;require("FAILED".equals(e.get("state"))&&"DEFINITIVE_REJECTION".equals(e.get("no_effect_basis"))&&e.get("no_effect_verified_at")!=null&&Long.valueOf(1).equals(e.get("provider_proof_reference_shape"))&&m.get("storeInstanceId").equals(e.get("proof_store")),PROVENANCE_UNAVAILABLE);references.add(Map.of("executionId",e.get("id"),"executionRequestHash",e.get("request_hash"),"receiptId",e.get("proof_receipt"),"proofDigest",e.get("proof_digest")));}references.sort(Comparator.comparing(x->(String)x.get("executionId")));require(references.equals(m.get("priorProofs")),PROVENANCE_UNAVAILABLE);}
 static void logical(Map<String,Object> m,String source,String fingerprint,TranscriptAcquisitionBudget.Ledger budget){validate(m,budget);budget.row(12);var logical=new TreeMap<String,Object>();logical.put("schema","ama.knowledge-publish.v1");logical.put("domain","KNOWLEDGE_PUBLISH");for(String k:List.of("providerId","publicationId","confirmationId","businessKey","libraryId","folderId","renderArtifact","payloadSha256"))logical.put(k,m.get(k));logical.put("sourceManifestHash",source);logical.put("inputFingerprint",fingerprint);require(ControlledKnowledgeClient.digest(ControlledKnowledgeClient.canonical(logical,budget)).equals(m.get("logicalRequestHash")),FINGERPRINT_MISMATCH);}
 private static String text(Map<?,?> m,String key,int max){Object x=m.get(key);require(x instanceof String,PROVENANCE_UNAVAILABLE);String s=(String)x;require(!s.isBlank()&&s.codePointCount(0,s.length())<=max,PROVENANCE_UNAVAILABLE);return s;}
 private static long number(Object n,long min){require(n instanceof Integer||n instanceof Long,PROVENANCE_UNAVAILABLE);long value=((Number)n).longValue();require(value>=min&&value<=Long.MAX_VALUE-1,PROVENANCE_UNAVAILABLE);return value;}
}
